 p=Path('lean/StratonovichHAMAudit')/(name+'.lean');ls=p.read_text().splitlines();print('\\nFILE '+str(p))
 for i,x in enumerate(ls):
  if re.match(r'"'^(?:theorem|def|lemma|variable)'"\\b',x):
